// Package invui draws menus in a chest window kept open while the server
// rewrites its slots: every element of a screen is a slot whose item and
// name the inventoryui pack's sg_menu.json draws (generated by
// tools/invuigen from this layout), and a press on a slot drops one item,
// which the server cancels and answers.
package invui

// Marker in the window title makes the pack draw the menu window.
const Marker = "§s§g§m§u"

// The slots every screen shares: the screen's key, its title, its body
// text, a second text (a split screen's status) and the page arrows of a
// split screen.
const (
	SlotKey   = 0
	SlotTitle = 1
	SlotBody  = 2
	SlotInfo  = 3
	SlotPrev  = 4
	SlotNext  = 5
)

// Tabs are the tabs over the window: an icon and a button slot each.
const (
	Tabs     = 8
	TabIcon0 = 6
	TabBtn0  = TabIcon0 + Tabs
)

// Bars are the buttons of the control bar, left of the close button.
const (
	Bars     = 6
	BarIcon0 = TabBtn0 + Tabs
	BarBtn0  = BarIcon0 + Bars
)

// Rows are the elements with an icon and a label: an icon and a button slot
// each. The screen's layout draws them as list rows, cards or actions.
const (
	Rows     = 48
	RowIcon0 = BarBtn0 + Bars
	RowBtn0  = RowIcon0 + Rows
)

// Cells are the item slots of a screen's grid: one slot each, holding the
// item itself named with its tooltip.
const (
	Cells = 111
	Cell0 = RowBtn0 + Rows
)

// SlotLogo and SlotGame are the logo and the game's name the lobby draws over
// its screens (KeyLobby).
const (
	SlotLogo = Cell0 + Cells
	SlotGame = SlotLogo + 1
)

// Size is the number of slots of the menu window: the most a window was seen
// to read (bedrock-research HOST-16 and the entity examples use 243).
const Size = SlotGame + 1

// The slots of the home screen (KeyHome): the profile card, the square
// buttons at the top right with their badges, the tiles down the left, the
// feed lines, the chosen save's card, the play and manage buttons and the
// overlay panel. Row numbers count from RowIcon0 and RowBtn0, cells from
// Cell0.
const (
	HomeProfileRow = 0
	HomeCornerRow0 = 1
	HomeCorners    = 6
	HomeSideRow0   = HomeCornerRow0 + HomeCorners
	HomeSides      = 8
	HomeSaveRow    = HomeSideRow0 + HomeSides
	HomePlayRow    = HomeSaveRow + 1
	HomeManageRow  = HomePlayRow + 1
	HomeOverRow0   = HomeManageRow + 1
	HomeOvers      = 6

	HomeTitleCell  = 0
	HomeLineCell   = 1
	HomeFillCell   = 2
	HomeBadgeCell0 = 3
	HomeFeedCell0  = HomeBadgeCell0 + HomeCorners
	HomeFeeds      = 8
	HomeHeadCell   = HomeFeedCell0 + HomeFeeds
	HomeLineCell0  = HomeHeadCell + 1
	HomeLines      = 4
	HomeSubCell    = HomeLineCell0 + HomeLines
	HomeOverTitle  = HomeSubCell + 1
	HomeOverBody   = HomeOverTitle + 1

	// HomeFillSteps is how many widths the profile's bar is drawn in.
	HomeFillSteps = 20
)

// The slots of the range screen (KeyRange): an axis a line, the offset's x,
// y and z then the reach's, each with its value in a cell and a minus and a
// plus button in the rows; the two headings in the cells after the axes and
// the 3D preview's box ("v1" to "v6", RangePreviews) in the next. The rows
// from RangeRow0 are list rows.
const (
	RangeAxes  = 6
	RangeHead0 = RangeAxes
	RangeHead1 = RangeAxes + 1
	RangeView  = RangeAxes + 2
	RangeRow0  = 2 * RangeAxes
)

// RangePreviews are the sizes of the boxes the range screen's 3D preview
// draws, each a cube from (-size/2, PreviewY, -size/2), left as a client
// only copy of the area being set.
var RangePreviews = [...]int{10, 16, 24, 32, 48, 64}

// PreviewY is the height of the bottom of the preview boxes.
const PreviewY = 256

// The layouts of the screens, by the key in SlotKey. KeyList after a key
// draws it on the list page (the body over the layout's content), and
// KeyRows the list rows under that content.
const (
	KeyList      = "L"
	KeyMenu      = "mn"
	KeyCards     = "cd"
	KeyGrid      = "gd"
	KeyBoard     = "bd"
	KeySplit     = "sp"
	KeyListSplit = "ls"
	KeyHome      = "hm"
	// KeyLoading draws the loading screen over the whole screen: the
	// picture in the first row's icon, the title in SlotTitle, the small
	// line under it in SlotInfo, the line ending in dots in SlotBody and the
	// tip in the first cell.
	KeyLoading = "ld"
	KeyRange   = "rg"
	KeyRows      = "Q"
	// KeyLobby after a key draws the lobby's logo and name over the screen.
	KeyLobby = "Y"
	// KeyOverlay after the home key draws the overlay panel.
	KeyOverlay = "V"
)

// Family markers say which group of kinds a slot belongs to: the pack draws
// one shape per family and tells its kinds apart with small parts only.
const (
	FamRow  = "§z§g"
	FamSlot = "§z§l"
	FamMini = "§z§k"
)

// The columns of the cell grids of the layouts.
const (
	GridColumns  = 17
	BoardColumns = 11
	SplitColumns = 8
	SplitCells   = 48
	RightColumns = 7
	CardColumns  = 4
	ListRows     = 32
)

// Kind markers end a slot's name and say what the slot draws. They are
// invisible format codes the pack takes off the text.
const (
	KindRow       = "§z§a"
	KindStatic    = "§z§s"
	KindChosen    = "§z§c"
	KindHeading   = "§z§h"
	KindDivider   = "§z§d"
	KindToggleOff = "§z§v"
	KindToggleOn  = "§z§x"
	KindTab       = "§z§t"
	KindTabOn     = "§z§u"
	KindBar       = "§z§b"
	KindHelp      = "§z§q"
	KindIcon      = "§z§i"
	KindFrame     = "§z§f"
	KindArrow     = "§z§w"
	KindText      = "§z§y"
	KindMini      = "§z§m"
	KindMiniView  = "§z§n"
	KindBlank     = "§z§e"
)

// Kinds are the kind markers in the order the pack strips them.
var Kinds = []string{KindRow, KindStatic, KindChosen, KindHeading, KindDivider, KindToggleOff, KindToggleOn, KindTab, KindTabOn, KindBar, KindHelp, KindIcon, KindFrame, KindArrow, KindText, KindMini, KindMiniView, KindBlank, FamRow, FamSlot, FamMini}
